def solve(s: str) -> bool:
    """Return True if brackets in s are balanced and properly nested.
    Considers (), [], {} and ignores other characters.
    """
    stack = []
    opening = set('([{')
    matches = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in matches:
            if not stack or stack[-1] != matches[ch]:
                return False
            stack.pop()
    return not stack

