def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings, each either an integer or one of '+', '-', '*', '/'.
    Division truncates toward zero as per problem statement.
    Returns integer result.
    """
    stack = []
    for t in tokens:
        if t in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # division
                # Python's int division truncates toward negative infinity, so use int() on true division
                stack.append(int(a / b))
        else:
            stack.append(int(t))
    return stack[0] if stack else 0

