{"task_id": "T39", "code": "def solve(a: str, b: str) -> int:
    # Use the classic DP algorithm but keep only two rows to save memory and improve speed.
    # Ensure we iterate over the shorter string as columns to minimise inner loop.
    if len(a) < len(b):
        a, b = b, a  # make a the longer string
    # now len(a) >= len(b)
    previous = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        current = [i] + [0] * len(b)
        for j, cb in enumerate(b, 1):
            if ca == cb:
                cost = 0
            else:
                cost = 1
            # deletion (previous[j] + 1), insertion (current[j-1] + 1), substitution (previous[j-1] + cost)
            current[j] = min(previous[j] + 1, current[j-1] + 1, previous[j-1] + cost)
        previous = current
    return previous[-1]"}

