def solve(a: str, b: str) -> int:
    """Compute Levenshtein distance between a and b using DP with O(min(n,m)) space."""
    n, m = len(a), len(b)
    if n == 0:
        return m
    if m == 0:
        return n
    # Ensure b is the shorter for less space
    if m > n:
        a, b = b, a
        n, m = m, n
    previous = list(range(m + 1))
    for i in range(1, n + 1):
        current = [i] + [0] * m
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                cost = 0
            else:
                cost = 1
            current[j] = min(
                previous[j] + 1,        # deletion
                current[j - 1] + 1,     # insertion
                previous[j - 1] + cost  # substitution
            )
        previous = current
    return previous[m]

